#!/usr/bin/env node
// ACCESSION — turns art/ into js/view/art.gen.js: sprite grids, 64×64 label close-ups and
// palettes (BUILD.md §9.1). Close-up rows are run-length encoded ("o{15}" is 15 o's).
// Usage: node tools/build-art.js [--check]   (--check fails if the generated file is stale)
'use strict';
const fs = require('node:fs'), path = require('node:path');
const root = path.join(__dirname, '..');
const out = path.join(root, 'js/view/art.gen.js');

function load(file) {
  const meta = {}, rows = [];
  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
    if (line.startsWith('#')) { const i = line.indexOf(':'); meta[line.slice(1, i).trim()] = line.slice(i + 1).trim(); }
    else if (line.trim()) rows.push(line.replace(/\s+$/, ''));
  }
  return { meta, rows };
}

const sprites = {};
const dir = path.join(root, 'art/sprites');
for (const f of fs.readdirSync(dir).filter(f => f.endsWith('.txt')).sort()) {
  const { meta, rows } = load(path.join(dir, f));
  const size = rows.length;
  if (rows.some(r => r.length !== size)) throw new Error(`${f}: rows must be ${size} wide`);
  sprites[f.slice(0, -4)] = { kind: meta.kind || 'exhibit', silhouette: meta.silhouette || '', size, rows };
}
// Close-ups: a colour layer and a shade layer, each 64 rows of 64, for a sprite that exists.
const closeups = {};
const rle = r => r.replace(/(.)\1{3,}/g, m => m[0] + '{' + m.length + '}');
const cdir = path.join(root, 'art/closeups');
for (const f of fs.existsSync(cdir) ? fs.readdirSync(cdir).filter(f => f.endsWith('.txt')).sort() : []) {
  const name = f.slice(0, -4), layers = { colour: [], shade: [] };
  let at = null;
  for (const line of fs.readFileSync(path.join(cdir, f), 'utf8').split('\n')) {
    if (line === '# colour') at = 'colour'; else if (line === '# shade') at = 'shade';
    else if (!line.startsWith('#') && line.trim() && at) layers[at].push(line.replace(/\s+$/, ''));
  }
  if (!sprites[name]) throw new Error(`art/closeups/${f}: no sprite art/sprites/${f}`);
  for (const k of ['colour', 'shade']) if (layers[k].length !== 64 || layers[k].some(r => r.length !== 64)) throw new Error(`art/closeups/${f}: the ${k} layer must be 64 rows of 64`);
  for (let y = 0; y < 64; y++) for (let x = 0; x < 64; x++) if (!'.+-='.includes(layers.shade[y][x])) throw new Error(`art/closeups/${f}: shade '${layers.shade[y][x]}' at ${x},${y}`);
  closeups[name] = { colour: layers.colour.map(rle), shade: layers.shade.map(rle) };
}
const palettes = JSON.parse(fs.readFileSync(path.join(root, 'art/palettes.json'), 'utf8'));
delete palettes._doc;
const text = "// ACCESSION — generated by tools/build-art.js from art/. Do not edit by hand.\n'use strict';\nconst ART = " +
  JSON.stringify({ palettes, sprites, closeups }) + ';\n';
if (process.argv.includes('--check')) {
  const cur = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
  if (cur !== text) { console.log('art.gen.js is out of date: run node tools/build-art.js'); process.exit(1); }
  console.log(`art: ${Object.keys(sprites).length} sprites, ${Object.keys(closeups).length} close-ups, up to date`);
} else {
  fs.writeFileSync(out, text);
  console.log(`wrote js/view/art.gen.js: ${Object.keys(sprites).length} sprites, ${Object.keys(closeups).length} close-ups, ${(text.length / 1024).toFixed(0)} KB`);
}
